# Generated by KernelGen: https://github.com/flagos-ai/KernelGen
import torch
import triton
import triton.language as tl

_VECTORCORE_CACHE = {}


def _num_vectorcore():
    # Pure vector elementwise kernel -> cap launched programs at the target's
    # vector-core count. Query the device at call time (B2-portable); never
    # hard-code a B4/B3 physical count.
    dev = torch.npu.current_device()
    cached = _VECTORCORE_CACHE.get(dev)
    if cached is not None:
        return cached
    n = 40
    try:
        props = triton.runtime.driver.active.utils.get_device_properties(dev)
        value = props.get("num_vectorcore") if isinstance(props, dict) else None
        if isinstance(value, int) and value > 0:
            n = value
    except Exception:
        pass
    _VECTORCORE_CACHE[dev] = n
    return n


@triton.jit
def _square_kernel(A_ptr, numel, BLOCK_SIZE: tl.constexpr):
    # Contiguous partition: each program owns one dense chunk [start, end) and
    # strides over BLOCK_SIZE tiles inside it. No interleaving across programs.
    pid = tl.program_id(0)
    nprog = tl.num_programs(0)
    per = (numel + nprog - 1) // nprog
    start = pid * per
    end = tl.minimum(start + per, numel)
    for s in range(start, end, BLOCK_SIZE):
        offs = s + tl.arange(0, BLOCK_SIZE)
        mask = offs < end
        x = tl.load(A_ptr + offs, mask=mask)
        tl.store(A_ptr + offs, x * x, mask=mask)


def _block_size(dtype):
    # Half the UB-ceiling tile to leave room for a deeper software pipeline
    # (num_stages=4): 6 live buffers x bytes/elem of the smaller tile is well
    # under 192KB, letting the compiler overlap DMA with compute on L2-resident
    # mid-size workloads.
    if dtype.itemsize <= 2:
        return 8192
    return 4096


def square_(A):
    numel = A.numel()
    if numel == 0:
        return A

    if A.is_contiguous():
        A_flat = A.view(-1)
    else:
        A_flat = A.contiguous().view(-1)

    bs = _block_size(A.dtype)
    tiles = triton.cdiv(numel, bs)
    grid = (min(tiles, _num_vectorcore()),)
    _square_kernel[grid](A_flat, numel, BLOCK_SIZE=bs, num_stages=4)

    return A
